#include <stdio.h>
int main(void){int total,holes,n,need,sum=0,largest=0;printf("Total free memory (KB): ");if(scanf("%d",&total)!=1||total<0)return 1;printf("Number of free holes: ");if(scanf("%d",&n)!=1||n<0)return 1;for(int i=0;i<n;i++){printf("Hole %d (KB): ",i+1);if(scanf("%d",&holes)!=1||holes<0)return 1;sum+=holes;if(holes>largest)largest=holes;}printf("Request size (KB): ");if(scanf("%d",&need)!=1||need<0)return 1;printf("Total listed free=%d KB (reported total=%d KB)\n",sum,total);if(need<=largest)puts("Request can fit in one hole (contiguous allocation).");else if(need<=sum)puts("Enough total free memory, but no single hole fits: external fragmentation.");else puts("Insufficient total free memory.");return 0;}
